INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('hash:62ac5170f57d0f8d3137fc84ccaa42347e705408b37310a6845bddca29d68bdd', '2026-Q1', 'Mar/2026', '2026-03-23T18:10'::timestamptz, 'Camila Gomes Linck', 'camila gomes linck', 'PHARUS', 'Gabriel Oliveira', 7.0, 'Neutro', 10.0, 10.0, 5.0, NULL, 'Sim, em grande parte', 'Sim', NULL, NULL, NULL, 'Eu vejo que a proposta é muito boa mas ando notando que teria sido mais proveitoso eu esperar mais um ano para entrar para a QuartaVia, pois os valores que consigo investir no momento e o que eu tenho disponível pra investir ainda sao valores baixos para poder aplicar diferentes estrategias. E considerando o valor do produto Quartavia nao vai ter tanta vantagem nesse primeiro ano. Entao minha sugestao seria deixar mais claro na captacao de novos clientes o quanto cada cliente precisa ter disponível pra investir e aportar para fazer valer a pena os 20k do produto de vcs. Mas no geral gosto bastante do atendimento, da ideia, do meu plano e das estratégias que estao me apresentando.', NULL, 'Ter bom retorno na estrategia de leilao que participei em janeiro e conseguir aumentar meus aportes para participar de mais estrategias.', 'Nao…', '7.0', '10/2025', 'nova jornada (backoffice/QV360)', 'NPS_Q1_2026_ENVIADO_MARCO.xlsx', 'pharus 2', NULL, 'aba PHARUS da planilha', 'MARÇO') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.